export function initKeyboardShortcuts(){document.addEventListener("keydown",(e)=>{const isInput=e.target.matches("input,textarea,[contenteditable]");const isModalOpen=document.getElementById("col-modal")?.style.display==="flex";if(e.ctrlKey && e.key==="Enter" && !isInput && !isModalOpen){e.preventDefault();if(window.ysqlvizApp?.joins?.addRowAndFocus){window.ysqlvizApp.joins.addRowAndFocus(0);}}if(e.ctrlKey && e.key==="n" && !isInput && !isModalOpen){e.preventDefault();if(window.ysqlvizApp?.joins?.addTableAndRender){window.ysqlvizApp.joins.addTableAndRender();}}if(e.ctrlKey && e.shiftKey && e.key==="R" && !isInput && !isModalOpen){e.preventDefault();if(confirm("Reset all data?")&& window.ysqlvizApp?.joins?.resetAllAndRender){window.ysqlvizApp.joins.resetAllAndRender();}}if(e.key==="Escape" && isModalOpen){document.getElementById("col-modal").style.display="none";}});if(!localStorage.getItem("shown-shortcuts-hint")){setTimeout(()=>{if(window.ysqlvizApp?.joins?.showToast){window.ysqlvizApp.joins.showToast("⌨️ Ctrl+Enter:Add row | Ctrl+N:Add table | Ctrl+Shift+R:Reset","success",6000);}},1500);localStorage.setItem("shown-shortcuts-hint","true");}}